uint32_t Mask(uint32_t crc) {
  static const uint32_t kMaskDelta = 0xa282ead8ul;
  return ((crc << 15) | (crc >> 17)) + kMaskDelta;
}

uint32_t Unmask(uint32_t masked_crc) {
  static const uint32_t kMaskDelta = 0xa282ead8ul;
  uint32_t crc = masked_crc - kMaskDelta;
  return (crc >> 15) | (crc << 17);
}

